import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int[] a = new int[3];
        int[] b = new int[3];

        for (int i = 0; i < 3; i++) {
            a[i] = fs.nextInt();
        }
        for (int i = 0; i < 3; i++) {
            b[i] = fs.nextInt();
        }

        int minimum = Math.max(0, Math.max(
                a[0] - b[0] - b[2],
                Math.max(a[1] - b[0] - b[1], a[2] - b[2] - b[1])
        ));

        int maximum = Math.min(a[0], b[1])
                + Math.min(a[1], b[2])
                + Math.min(a[2], b[0]);

        System.out.println(minimum + " " + maximum);
    }

    private static class FastScanner {
        private final InputStream input;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream input) {
            this.input = input;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = input.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }
    }
}

